const responses = $input.all();
const sources = $("Company sources").all();
const results = [];

for (let i = 0; i < responses.length; i++) {
  const response = responses[i];

  // Identify which company produced this API response
  const sourceIndex = response.pairedItem?.item ?? i;
  const source = sources[sourceIndex]?.json;

  if (!source) {
    throw new Error(`Missing company source for response ${i}`);
  }

  const raw = response.json;
  const isLever = source.ats === "lever";

  const jobs = isLever
    ? (Array.isArray(raw) ? raw : raw.data || [])
    : (raw.jobs || []);

  if (!Array.isArray(jobs)) {
    throw new Error(`Invalid jobs array for ${source.company}`);
  }

  for (const j of jobs) {
    const description = String(
      isLever
        ? (j.descriptionPlain || j.description || "")
        : (j.content || "")
    )
      .replace(/&lt;/gi, "<")
      .replace(/&gt;/gi, ">")
      .replace(/<[^>]*>/g, " ")
      .replace(/&nbsp;|&#160;/gi, " ")
      .replace(/&amp;/gi, "&")
      .replace(/&#39;|&apos;/gi, "'")
      .replace(/&quot;/gi, '"')
      .replace(/\s+/g, " ")
      .trim();

    results.push({
      json: {
        job_key: `${source.company}:${source.ats}:${j.id}`,
        company: source.company,
        job_title: isLever ? (j.text || "") : (j.title || ""),
        location: isLever
          ? (j.categories?.location || "")
          : (j.location?.name || ""),
        apply_url: isLever
          ? (j.hostedUrl || j.applyUrl || "")
          : (j.absolute_url || ""),
        posted_date: isLever
          ? (j.createdAt
              ? new Date(j.createdAt).toISOString()
              : "")
          : (j.first_published || ""),
        updated_at: isLever
          ? ""
          : (j.updated_at || ""),
        description: description.slice(0, 13000),
        first_seen: new Date().toISOString(),
        match_score: 0,
        sponsorship_status: "not_specified",
        reason: "",
        notified: false
      },
      pairedItem: {
        item: i
      }
    });
  }
}

return results;

