// ============================================
// LOCATION HELPERS
// ============================================

function escapeRegex(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function containsPlace(text, place) {
  const pattern = new RegExp(
    `(^|[^a-z])${escapeRegex(place)}(?=$|[^a-z])`,
    "i"
  );

  return pattern.test(text);
}

function isUSLocation(location) {
  const loc = String(location || "").trim();

  if (!loc) return false;

  // Reject explicitly foreign locations
  const foreign =
    /\b(canada|toronto|montreal|montréal|vancouver|ottawa|india|united kingdom|uk|london|europe|germany|france|poland|mexico|singapore|australia|netherlands|ireland|japan|brazil|china|spain|italy|sweden|switzerland|denmark|norway|finland|portugal|israel|united arab emirates|dubai|uae|south korea|taiwan|hong kong)\b/i;

  if (foreign.test(loc)) {
    return false;
  }

  // Explicit US locations
  if (/\b(united states|usa|u\.s\.a\.|u\.s\.)\b/i.test(loc)) {
    return true;
  }

  // City followed by US state abbreviation
  const matches =
    [...loc.matchAll(/,\s*([A-Za-z]{2})\b/g)];

  if (matches.some(
    m => usStates.has(m[1].toUpperCase())
  )) {
    return true;
  }

  // Full US state names
  if (usStateNames.some(
    state => containsPlace(loc, state)
  )) {
    return true;
  }

  // Recognized US city names
  if (usCities.some(
    city => containsPlace(loc, city)
  )) {
    return true;
  }

  return false;
}

