for (const item of inputs) {
  const html = String(
    item.json.data ?? item.json.body ?? ''
  );

  if (!html.includes('iCIMS_JobCardItem')) {
  if (
    !html.includes('iCIMS_MainWrapper') &&
    !html.includes('iCIMS_ListingsPage')
  ) {
    throw new Error(
      'Unexpected response: iCIMS listing HTML not found'
    );
  }

  // Valid iCIMS page with no job listings.
  continue;
}

  const cards = html.match(
    /<li\b[^>]*class=["'][^"']*iCIMS_JobCardItem[^"']*["'][^>]*>[\s\S]*?<\/li>/gi
  ) || [];

  for (const card of cards) {
    const linkMatch = card.match(
      /<a\b[^>]*href=["'](https:\/\/jobs-childrensmercykc\.icims\.com\/jobs\/\d+\/[^"']+)["'][^>]*>[\s\S]*?<h3[^>]*>([\s\S]*?)<\/h3>/i
    );

    if (!linkMatch) continue;

    const url = linkMatch[1];
    const title = clean(linkMatch[2]);

    const id = url.match(/\/jobs\/(\d+)\//)?.[1];
    if (!id) continue;

    const locationMatch = card.match(
      /class=["'][^"']*header left[^"']*["'][^>]*>[\s\S]*?<span[^>]*>([\s\S]*?)<\/span>[\s\S]*?<span[^>]*>([\s\S]*?)<\/span>/i
    );

    const rawLocation = clean(locationMatch?.[2]);

    const location = rawLocation
      .replace(/^US-MO-/, '') 
      .replace(/^US-KS-/, '');

    const state = rawLocation.startsWith('US-MO-')
      ? 'MO'
      : rawLocation.startsWith('US-KS-')
      ? 'KS'
      : '';

    jobs.push({
      json: {
        job_key: `ChildrensMercy:icims:${id}`,
        company: "Children's Mercy Hospital",
        job_title: title,
        location: state
          ? `${location}, ${state}`
          : rawLocation,
        apply_url: url,
        posted_date: '',
        description: '',
        first_seen: new Date().toISOString(),
        match_score: 0,
        sponsorship_status: 'not_specified',
        reason: '',
        notified: false
      }
    });
  }
}

return jobs;

